  { n = "Booster Blitz", t = "Card", c = "", o = "2 players | 2 packs | 10 minutes\nOBJECTIVE:\nBest your opponent in a series of fast Magic games using only the cards in a single pack!\nGET READY:\nEach player opens a pack and makes four face-down piles of three cards each using the Magic cards inside. Players make their piles with the goal of winning a series of Magic games with these modified rules:\nPlayers start at 5 life, have infinite mana, and cannot lose by drawing from an empty library.\nLET'S PLAY:\nRandomly determine who goes first. Each player chooses which pile their opponent will use for each round. Then both players draw all three of their cards and play a game of Magic. When a player loses a game, they get to go first in the next game.\nTO WIN:\nThe first player to win two games wins the match.", i = "cb778688-af4c-4140-a17f-4faae0db83e2" },
  { n = "Booster Sleuth", t = "Card", c = "", o = "2 players | 2 packs | 10 minutes\nOBJECTIVE:\nUnlike Jace, not all of us can rely on telepathy to solve a mystery. Using other cards as clues, discover all the facts about your opponent's mystery card.\nGET READY:\nRandomly determine who goes first—that player is the Secretkeeper, and their opponent is the Detective. First, the Secretkeeper opens a pack and removes any lands and cards without Magic card backs. Next, they shuffle the remaining cards and pick one at random. That card is the mystery card. Finally, the Secretkeeper gives the Detective the rest of the cards, and the game begins.\nLET'S PLAY:\nThe Detective must correctly guess four facts", i = "bdbc85f5-a5fc-4b30-b622-f2cbdecdb977" },
  { n = "Bounty: Eriana, Wrecking Ball", t = "Card", c = "", o = "At the beginning of your end step, if you committed a crime this turn, collect your reward. (Targeting opponents, anything they control, and/or cards in their graveyards is a crime.)", i = "acd27632-4c28-4dc3-90ad-b94fe176b91a" },
  { n = "Bounty: Frankie The Fang", t = "Card", c = "", o = "At the beginning of your end step, if the player with the most life or tied for most life as the turn began was dealt combat damage this turn, collect your reward.", i = "cd756281-c63f-44cf-88b5-e5d461195acd" },
  { n = "Bounty: Gorra Tash and Silas", t = "Card", c = "", o = "At the beginning of your end step, if all opponents were dealt combat damage this turn, collect your reward.", i = "415c0799-2ab4-4f88-be9b-d47c07d7a44b" },
  { n = "Bounty: Lord Fajjal", t = "Card", c = "", o = "At the beginning of your end step, if a land card was put into your graveyard from anywhere this turn, collect your reward.", i = "5e54793b-a5e4-4391-8bbb-509a99e08bcb" },
  { n = "Bounty: Lyssa, Sterling Collector", t = "Card", c = "", o = "At the beginning of your end step, if the player with the most cards in hand or tied for most cards as the turn began was dealt combat damage this turn, collect your reward.", i = "f7a095ac-8316-4824-bad5-0b74a58dd2e9" },
  { n = "Bounty: Miron Tillas Jr.", t = "Card", c = "", o = "At the beginning of your end step, if the nearest opponent to your left as the turn began was dealt combat damage this turn, collect your reward.", i = "0fd5b9c3-9c18-446d-9d81-7a3a90d7bbee" },
  { n = "Bounty: Paq, Fleeting Filcher", t = "Card", c = "", o = "At the beginning of your end step, if there are four or more card types among cards in your graveyard, collect your reward.", i = "fe1ca7a3-025f-4ab4-9764-c0b11e010f97" },
  { n = "Bounty: Rissa \"Blades\" Lee", t = "Card", c = "", o = "At the beginning of your end step, if you cast an instant or sorcery spell this turn while you had two or more instant and/or sorcery cards in your graveyard, collect your reward.", i = "1fbba46a-e9f1-43d7-820f-7c9c43244aa5" },
  { n = "Bounty: Sleepy Sovka", t = "Card", c = "", o = "At the beginning of your end step, if you cast no spells this turn, collect your reward.", i = "590120cd-b072-4480-9652-f9dec7de4065" },
  { n = "Bounty: Squeakers the Sly", t = "Card", c = "", o = "At the beginning of your end step, if a legendary creature you controlled attacked alone this turn, collect your reward.", i = "25a24ce6-ad4d-46f7-9705-42318d1f41ff" },
  { n = "Bounty: The Outsider", t = "Card", c = "", o = "At the beginning of your end step, if you cast a spell from anywhere other than your hand this turn, collect your reward.", i = "92d36a9a-c39c-41e6-9f31-4fcb5e820bd9" },
  { n = "Bounty: Vara Beth Hannifer", t = "Card", c = "", o = "At the beginning of your end step, if the nearest opponent to your right as the turn began was dealt combat damage this turn, collect your reward.", i = "4c6cd098-5a40-4031-af21-8746165ae442" },
  { n = "Brainiac", t = "Token Creature — Brainiac", p = "1", u = "1", c = "R", o = "", i = "af1a8115-127d-4268-a4d0-95360862e5fb" },
  { n = "Brian Hacker Bio", t = "Card", c = "", o = "Twenty-three-year-old professional Magic® player Brian Hacker of San Diego, California, thought he had a good chance of winning the finals with his white weenie deck. Hacker said his deck was well set up to defeat his opponents with its twenty-something aggressive creatures—including a number of shadow and en-Kor creatures. Unlike traditional white weenie decks, which rely on Armageddon as a major threat card, Hacker's deck uses Cataclysm, which he feels better complements the use of Empyrial Armor.", i = "a8d38af0-a960-4a49-9896-1e11f53eab5b" },
  { n = "Brian Hacker Decklist", t = "Card", c = "", o = "", i = "0c85b8a5-cf76-4952-9fe0-cb7d2f86fead" },
  { n = "Brian Kibler Bio", t = "Card", c = "", o = "Pro Tour™ veteran Brian Kibler piloted his green-white-red \"Red Zone 2K2\" deck to an impressive finish at this year's Worlds. This deck quickly tried to put its many creatures into the \"red zone,\" the attacking zone on the playmats used on the Pro Tour circuit. The twenty-one—year-old Kibler attends Emory University in Atlanta, Georgia, and is part of the \"Mini Colony\" playtest group that designed the Red Zone 2K2 deck.", i = "3746d381-9c73-4d74-aa7f-79426e163eb7" },
  { n = "Brian Kibler Decklist", t = "Card", c = "", o = "", i = "d938bdec-eb97-4b3e-abdc-6eddd7bcd44e" },
  { n = "Brian Selden Bio", t = "Card", c = "", o = "Brian Selden, a seventeen-year-old high school student from San Diego, California, says his deck revolves around the interaction between Survival of the Fittest and Recurring Nightmare. The former is used to put creatures into the graveyard and the latter can then bring them into play. With this combo, Selden is able to use his creatures to react to an opponent's threats. The deck also contains over twenty creatures, many of which have an effect when they enter play or perform some other useful function, such as the Spike Weaver. Unlike many similar decks, Selden's dips into blue, primarily for Lobotomy. He said this was the key to many of his victories.", i = "cdbe9dfc-3c91-40ac-9740-167e17746e94" },
  { n = "Brian Selden Decklist", t = "Card", c = "", o = "", i = "b172a9c5-802d-46af-a97b-86b0bce4596a" },
  { n = "Bushy Bodyguard", t = "Token Creature — Squirrel Warrior", p = "1", u = "1", c = "G", o = "When this creature enters, you may forage. If you do, put two +1/+1 counters on it.\n(This token's mana cost is {1}{G}.)", i = "c247d48f-d1e9-4b28-b372-bf4eea67cb8c" },
  { n = "Butterfly", t = "Token Creature — Insect", p = "1", u = "1", c = "G", o = "Flying", i = "d7636957-f183-4f58-87a6-056cde657114" },
  { n = "Cadet", t = "Token Creature — Wizard Soldier", p = "2", u = "2", c = "", o = "", i = "8f4534d8-2783-484f-8ebf-a47b1cc4c6df" },
  { n = "Careful Study (minigame)", t = "Card", c = "", o = "2-6 players | 1 pack | 5 minutes\nOBJECTIVE:\nTake turns memorizing _Magic_ cards and trying to stump your opponent with questions!\nGET READY:\nSplit up into two teams of one or more players. Randomly determine which team goes first, and then open a pack and remove any remaining land cards and any cards without _Magic_ card backs. Each team then picks a card and puts it face down on the table without looking at it.\nLET'S PLAY:\nOn your turn, your team has 30 seconds to examine your card before handing it over to the opposing team. Then they ask your team five questions about your card. Once you've answered them all, note your score. Now it's your team's turn to ask the questions! Questions can be about anything on the card.", i = "f84993cc-2e5e-449b-bbba-8c1b8ca26b40" },
  { n = "Carlos Romão Bio", t = "Card", c = "", o = "Carlos Romão played the same style of deck that many people at this year's World Championships chose to play: blue-black Psychatog. He simply played his version better than everyone else playing theirs. Romão, known as \"Jaba\" to his friends, was a perfect 6-0 during the Swiss portion of the tournament, posting a stunning 12-0 game record. This twenty-year-old native of São Paulo, Brazil, has been widely regarded as one of the best players in South America. His deck tried to stay alive long enough to play Upheaval, while floating mana to replay Psychatog on the same turn.", i = "baf955be-0742-483d-a7df-e58792f31817" },
  { n = "Carlos Romão Decklist", t = "Card", c = "", o = "", i = "62a4afbd-6325-4451-9840-6d5fda836118" },
