  { n = "Council of Reeds", t = "Token Legendary Creature — Human Scientist Hero", p = "2", u = "2", c = "", o = "The \"legend rule\" doesn't apply to creatures you control.\nAt the beginning of combat on your turn, if you've cast a noncreature spell this turn, create a token that's a copy of Council of Reeds.\n(This token's mana cost is {2}{U}.)", i = "b1776802-c1d7-4d4d-926f-ab3748942b62" },
