  { n = "Cyber Simulacrum", t = "Card", c = "", o = "2-6 Players | 1 Pack | 10 Minutes\nOBJECTIVE:\nSometimes technology is useful, and sometimes it's downright confusing! Deduce the identity of your cards using only images from the internet.\nGET READY:\nOpen a booster pack and remove all ad, token, and art cards. Deal one card face down to each player, setting the rest aside. Each player secretly looks at their card, then searches its card name using an internet search engine. Navigate to the first three image results that are not of a Magic card or Magic art, then choose one of those images. If you're unsure if something depicts Magic art, use your best judgment.", i = "1bbcdd5d-e24c-4ab2-b366-9312adf9e972" },
  { n = "Cyberman", t = "Artifact Creature — Cyberman", p = "2", u = "2", c = "", o = "(You can cover a face-down creature that has become a Cyberman with this reminder card. It's a 2/2 Cyberman artifact creature.)", i = "9bc273b8-05bb-4c8f-92b1-c178d4bbadb0" },
  { n = "Dack Fayden Emblem", t = "Emblem — Dack", c = "", o = "Whenever you cast a spell that targets one or more permanents, gain control of those permanents.", i = "c80136c2-7230-4fe5-b7dc-37ee32f1bd8e" },
  { n = "Dalek", t = "Token Artifact Creature — Dalek", p = "3", u = "3", c = "B", o = "Menace", i = "f176f6ec-1ff8-4cd4-b7a6-b95830532f6a" },
  { n = "Daniel Zink Bio", t = "Card", c = "", o = "Daniel Zink, a student from Bochum, Germany, players the control deck that defined this year's World Championships. The white-blue-green \"Wake\" deck is named after the powerful enchantment that's the heart of the deck. Once Mirari's Wake is in play, the deck produces more mana, draws more cards, counters more spells, and makes more Soldiers than opponents can possibly handle. Zink had help from fellow German and 2002-2003 Player of the Year Kai Budde in adapting the \"Wake\" deck to the post—Eigth Edition environment.", i = "a1352676-9a0e-44bc-972a-b2c26b99e529" },
  { n = "Daniel Zink Decklist", t = "Card", c = "", o = "", i = "93380a7d-8df1-4cce-bf88-67e3b73eb70c" },
  { n = "Daretti, Scrap Savant Emblem", t = "Emblem — Daretti", c = "", o = "Whenever an artifact is put into your graveyard from the battlefield, return that card to the battlefield at the beginning of the next end step.", i = "64ace1f4-51b5-4a6a-a730-859717efbd6d" },
  { n = "Dark Ascension Checklist", t = "Card", c = "", o = "(You can mark this card to represent a double-faced card in your library or hand.)\n☐ Loyal Cathar {W}{W}\n☐ Soul Seizer {3}{U}{U}\n☐ Chosen of Markov {2}{B}\n☐ Ravenous Demon {3}{B}{B}\n☐ Afflicted Deserter {3}{R}\n☐ Hinterland Hermit {1}{R}\n☐ Mondronen Shaman {3}{R}\n☐ Lambholt Elder {2}{G}\n☐ Scorned Villager {1}{G}\n☐ Wolfbitten Captive {G}\n☐ Huntmaster of the Fells {2}{R}{G}\n☐ Chalice of Life {3}\n☐ Elbrus, the Binding Blade {7}", i = "825c61e7-bf33-45ea-af78-97ab3bc96753" },
  { n = "Darkstar", t = "Token Legendary Creature — Dog", p = "2", u = "2", c = "BW", o = "", i = "19faca08-0eef-4da4-ab6f-c3aed63ac77b" },
  { n = "Darkstar Augur", t = "Token Creature — Bat Warlock", p = "1", u = "1", c = "B", o = "Flying\nAt the beginning of your upkeep, reveal the top card of your library and put that card into your hand. You lose life equal to its mana value.\n(This token's mana cost is {2}{B}.)", i = "01b55966-0910-484d-9b2b-0a59233c44c4" },
  { n = "Dave Humpherys Bio", t = "Card", c = "", o = "The Top 8 is familiar territory for professional Magic player Dave Humpherys. With over $130,000 in career winnings and a Pro Tour championship on his resume, \"The Hump\" advanced to the Worlds semifinals for the second year in a row where he lost to eventual champion Daniel Zink. The blue-green madness deck he played has been a Standard mainstay for more than a year. It revolves around Torment madness cards like Basking Rootwalla and Circular Logic, together with discard-enablers like Aquamoeba and Wild Mongrel. Humpherys, who recently earned his Ph.D. from MIT, credits this version of the deck to Norway's Sigurd Eskeland.", i = "2b490cfc-3a5a-4045-a53f-3395f61bb7a1" },
  { n = "Dave Humpherys Decklist", t = "Card", c = "", o = "", i = "4a4158c7-5f24-4b56-bb9e-ddc3e459b555" },
  { n = "Day", t = "Card", c = "", o = "(If it becomes day or night or if a daybound permanent enters the battlefield, track day/night for the rest of the game.)\nAs it becomes day, transform all nightbound permanents.\nIf a player casts no spells during their own turn, it becomes night next turn.", i = "dc26e13b-7a0f-4e7f-8593-4f22234f4517" },
  { n = "Day Vs. Night", t = "Card", c = "", o = "2 players | 2 packs | 5 minutes\nOBJECTIVE:\nBecome a defender of the day or a monster of the night in this rock-paper-scissors-style game.\nGET READY:\nRandomly determine who will use the power of **Day** and who will use the power of **Night**. Each player opens a booster and sets aside any cards without Magic card backs.\nLET'S PLAY:\nPlayers look at their hands, pick three cards, and then place their picked cards in a face down row in front of their opponent's row. Players reveal the pairs of cards from Day player's left to right simultaneously. Winning cards are decided as follows:\n• Red beats green\n• Green beats blue\n• Blue beats red\n• White is always a winning card for the Day player, but it's always a losing card for the Night player\n• Black is always a winning card for the Night player, but it's always a losing card for the Day player.", i = "e3cb0f04-d6fa-4dc3-8351-9dd9075583bc" },
