  { n = "Foraging Squirrels", t = "Card", c = "", o = "2-4 players | 2 packs | 5 min\nOBJECTIVE:\nYou're a cute squirrel, which is great; however, you need to collect food for the winter along with the rest of the squirrels, and you're all competing for the same food strewn across the forest floor. Scramble to get the best stuff!\nGET READY:\nOpen both packs and remove all cards without _Magic_ card backs. *Select one art card* and shuffle it in with the rest of the cards, which represent the food. Deal the cards face up in a 5x5 grid. Randomly determine who goes first.\nLET'S PLAY:\nOn your turn, choose a *color* (including colorless). Then move the art card either vertically or horizontally on the grid, skipping empty spaces and collecting each card in your path that matches your chosen color. (Reminder: Lands are colorless.) The art card can move in only one direction per turn, and", i = "bb2b0250-4b48-43bc-ad08-8fd9092bbba6" },
  { n = "Forest Dryad", t = "Token Land Creature — Forest Dryad", p = "1", u = "1", c = "G", o = "(This creature is affected by summoning sickness, and it has \"{T}: Add {G}.\")", i = "107be8ee-ee22-4d37-94f1-2a5b438fbe05" },
