  { n = "Gabriel Nassif Bio", t = "Card", c = "", o = "Twenty-year-old Gabriel Nassif is considered to be the best player never to have won a Pro Tour™ event. Designed to beat the ubiquitous \"Affinity\" decks, his blue-white control deck also plays well against anti-Affinity decks. Worlds marked the third time in the season that the Parisian had made it to the final day of a Pro Tour event, and his performance earned Nassif the coveted 2004 Player of the Year award—a title he will defend vigorously next year.", i = "06a5f33a-9357-46c5-bc3b-aba91581287e" },
