  { n = "Into the Story: Assassin Edition", t = "Card", c = "", o = "OBJECTIVE:\nCreate your own Assassin's Creed storyline, using the cards in your boosters as inspiration.\nGET READY:\nOpen two boosters for each player and remove any cards without magic card backs.Then sort the cards into separate piles for creature cards, land cards, and other noncreature cards. Shuffle the piles and place each of them face down.\nLET'S PLAY:\nGo through the beats of the other side of this card in order, revealing a card from the top of the specified pile or taking the specified action. Tell a story as you go. After a player tells a bit of the story for a beat, it's the next player's turn for the next story beat. If there are no cards of the requested type, players can make something up.", i = "6f98df20-e932-47a5-ba0c-ba17c0e11df0" },
  { n = "Into the Story: Horror Edition", t = "Card", c = "", o = "1-6 players | 1+ packs | 10 minutes\nOBJECTIVE:\nTell the best horror story you can, using the cards in your booster as inspiration.\nGET READY:\nOpen a booster for each player and remove any ad, token, and art cards. Then sort the cards into separate piles for double-faced cards (DFCs), single-sided creature and planeswalker cards, land cards, and all other noncreature cards. Shuffle the piles and place each of them face down.\nLET'S PLAY:\nGo through the beats of the story below in order, revealing a card from the top of the specified pile or taking the specified action. Tell a story as you go. After a player tells a bit of the story for a beat, it's the next player's turn for the next story beat. If there are no cards of the requested type, players can make something up.\n**Introduction**\n• Setting: a land\n• The characters: three creatures/planeswalkers\n• Why the characters are at the location: a noncreature card", i = "39fabb62-1644-4dc5-bb99-dc3508bd6681" },
  { n = "Intrepid Rabbit", t = "Token Creature — Rabbit Soldier", p = "1", u = "1", c = "W", o = "When this creature enters, target creature you control gets +1/+1 until end of turn.\n(This token's mana cost is {2}{W}.)", i = "3b1cd58d-c0bc-48e5-b6fa-fb222fba77ab" },
  { n = "Iridescent Vinelasher", t = "Token Creature — Lizard Assassin", p = "1", u = "1", c = "B", o = "Landfall — Whenever a land you control enters, this creature deals 1 damage to target opponent.\n(This token's mana cost is {B}.)", i = "2f55c677-dc14-4ae3-9518-0d80b528c3fb" },
  { n = "Ixalan Checklist", t = "Card", c = "", o = "(You can mark this card to represent a double-faced card in your library or hand.)\n☐ Legion's Landing {W}\n☐ Search for Azcanta {1}{U}\n☐ Arguel's Blood Fast {1}{B}\n☐ Vance's Blasting Cannons {3}{R}\n☐ Growing Rites of Itlimoc {2}{G}\n☐ Conqueror's Galleon {4}\n☐ Dowsing Dagger {2}\n☐ Primal Amulet {4}\n☐ Thaumatic Compass {2}\n☐ Treasure Map {2}", i = "4a8b3030-5495-404b-938c-8c4a387a1341" },
  { n = "Jace", t = "Token Planeswalker — Jace", c = "U", o = "−1: Surveil 1. (Look at the top card of your library. You may put that card into your graveyard.)\n−3: Draw a card.", i = "8d1e424f-6407-4f8c-bed2-eaf148237c81" },
  { n = "Jace, Telepath Unbound Emblem", t = "Emblem — Jace", c = "", o = "Whenever you cast a spell, target opponent puts the top five cards of their library into their graveyard.", i = "458e37b1-a849-41ae-b63c-3e09ffd814e4" },
  { n = "Jace, Unraveler of Secrets Emblem", t = "Emblem — Jace", c = "", o = "Whenever an opponent casts their first spell each turn, counter that spell.", i = "e5797bac-bf43-4c96-9f84-60db130a15bb" },
  { n = "Jakub Šlemr Bio", t = "Card", c = "", o = "Šlemr, a twenty-year-old computer analyst from Prague in the Czech Republic, said that he wasn't happy with his deck's 3—4 performance in the Standard (Type II) portion of the tournament. However, it came through for him in the elimination rounds. A black weenie deck at heart, it dips into all five colors. It also features a number of creatures that have an effect on entering play, like Man-o'-War, Uktabi Orangutan, and Nekrataal.", i = "fb38f4dd-b0ce-4613-a876-764897d29923" },
  { n = "Jakub Šlemr Bio (1999)", t = "Card", c = "", o = "1997 World Champion Jakub Šlemr came within two matches of becoming the first person to repeat as World Champion. The 22-year-old Prague native earned a flawless 6—0 resord during the Standard portion of the Swiss rounds. Šlemr, along with fellow teammate and quarterfinalist Gary Wise, played a mono-black deck coined \"Black Control.\" He used discard effects early with cards like Ravenous Rats, Duress, and Stupor. However, the majority of his deck was dedicated to board control with Cursed Scrolls, Powder Kegs, and Phyrexian Plaguelords.", i = "966b93ba-f671-4244-b879-aa20b355775a" },
  { n = "Jakub Šlemr Decklist", t = "Card", c = "", o = "", i = "fc79931b-36f7-4727-86d7-e92076c2fab9" },
  { n = "Jakub Šlemr Decklist (1999)", t = "Card", c = "", o = "", i = "071cda12-a2d4-447f-8382-22870b6dc5cf" },
  { n = "Jan Tomcani Bio", t = "Card", c = "", o = "Jan Tomcani, from Bratislava in the Slovak Republic, came out of nowhere to stun everyone by posting a perfect 6—0 record in the Standard portion of this year's Worlds. Tomcani then proved that his run was no fluke by working his way up to the quarterfinals, where he lost to Alex Borteh in a close five-game match. Tomcani played a version of \"Fires,\" the green-red deck that defined much of this year's metagame. Tomcani's version, which splashed black, follows the normal Fires archetype of playing cheap creatures followed by Fires of Yavimaya and big creatures like Blastoderm or Spiritmonger.", i = "006a2cce-dd8f-47d5-aedd-135e51ecfa23" },
  { n = "Jan Tomcani Decklist", t = "Card", c = "", o = "", i = "e2ffc06e-fed9-4241-9fa5-0d11858765a6" },
  { n = "Janosch Kühn Bio (1997)", t = "Card", c = "", o = "Kühn, a fifteen-year-old high-school student from Hanover, Germany, played a red, white, and blue deck with a balanced mix of speed and control. It uses cards like Incinerate and Swords to Plowshares to deal with opponents' fast creatures, while increasing the mana base with Thawing Glaciers. For late in the game, Disintegrate and Hammer of Bogardan are excellent finishing cards.", i = "c420f353-0d9f-44ad-a566-5ed0b58964c2" },
  { n = "Janosch Kühn Bio (2000)", t = "Card", c = "", o = "Hannover, Germany native Janosch Kühn joined an elite group of players in earning his second World Championship Top 8. Kühn played a red-green deck known as \"Angry 'Derm\" or \"Son of Hermit.\" The deck built up its mana early with Birds of Paradise or Llanowar Elves, and then followed that up with mana-denial cards like Stone Rain, Plow Under, and Avalanche Riders. Masticore and Blastoderm provided the finishing punch.", i = "fe1a99b3-5ff4-48d4-8603-7271f12269f4" },
  { n = "Janosch Kühn Decklist (2000)", t = "Card", c = "", o = "", i = "170c4817-104c-4a10-a796-6e62c5104920" },
  { n = "Janosch Kühn Decklist 1997", t = "Card", c = "", o = "", i = "2e8d223d-ede3-477b-8dd7-e4c58798b3f3" },
  { n = "Jaya Ballard Emblem", t = "Emblem — Jaya", c = "", o = "You may cast instant and sorcery spells from your graveyard. If a spell cast this way would be put into your graveyard, exile it instead.", i = "a02ffa48-e414-493c-af51-1400913f8af4" },
  { n = "Jaya, Fiery Negotiator Emblem", t = "Emblem", c = "", o = "Whenever you cast a red instant or sorcery spell, copy it twice. You may choose new targets for the copies.", i = "243a5830-d7a0-46c9-98c0-4d1dfc3ebc8c" },
  { n = "Jon Finkel Bio", t = "Card", c = "", o = "\"World Champion\" was the one honor Jon Finkel had yet to claim. His dominating performance at this year's World Championships earned him that title at last. Finkel played an explosive deck that is named after its most important card, Tinker. Fellow Team Antarctica member Dan O'Mahoney-Schwartz designed this monoblue deck. The deck used artifacts such as Grim Monolith, Metalworker, and Voltaic Key to quickly generate huge amounts of mana, and then used that mana to put large creatures into play.", i = "de9d6766-2b3c-4215-858b-5205702cbc8e" },
  { n = "Jon Finkel Decklist", t = "Card", c = "", o = "", i = "b905ddba-8808-45b3-81bf-406592e4c661" },
  { n = "Julien Nuijten Bio", t = "Card", c = "", o = "The youngest ever Magic® World Champion, Dutch wunderkind Julien Nuijten came out of nowhere to stun the field. Just fifteen years old, Nuijten proved that he can play with the best. Playing a green—white Astral Slide deck designed to destroy \"Affinity\", he posted a respectable 4-2 record on the Standard day at Worlds and then calmly swept the field on the final day. He says the inspiration for his deck came from an Internet article by Pro Tour™ veteran Brian Kibler.", i = "9022a74a-f758-4475-88af-164d9e5ecf31" },
  { n = "Julien Nuijten Decklist", t = "Card", c = "", o = "", i = "18eee350-4d70-4124-ae0d-a77f3bd7e948" },
  { n = "Junk", t = "Token Artifact — Junk", c = "", o = "{T}, Sacrifice this artifact: Exile the top card of your library. You may play that card this turn. Activate only as a sorcery.", i = "62c4a6f6-6425-4c0c-b35a-880fcab42aad" },
  { n = "Kai Budde Bio", t = "Card", c = "", o = "Known as the \"King of the Grand Prix,\" Kai Budde earned an unprecedented three Grand Prix titles in 1999. Though he went only 4—2 during the Swiss portion of the World Championships, he cruised through the Final 8 to become the 1999 World Champion. The 19-year-old Köln, Germany native played a red-artifact deck that contained more than 30 artifacts. He used those artifacts to quickly generate huge amounts of mana, with which he could play a big creature like Masticore or Covetous Dragon. He would then finish off his opponent with a well-timed Wildfire.", i = "9ed2329f-d055-4a60-955b-384722504278" },
  { n = "Kai Budde Decklist", t = "Card", c = "", o = "", i = "b62b648e-f572-4b3b-8315-983d27704b8c" },
