  { n = "Lizard", t = "Token Creature — Lizard", p = "8", u = "8", c = "R", o = "", i = "70345006-5cde-44f8-ab66-9d8163d4c4f6" },
  { n = "Llanowar Elves", t = "Token Creature — Elf Druid", p = "1", u = "1", c = "G", o = "{T}: Add {G}.", i = "cbcb0668-e88c-4462-b079-34f140c0277e" },
  { n = "Lolth, Spider Queen Emblem", t = "Emblem — Lolth", c = "", o = "Whenever an opponent is dealt combat damage by one or more creatures you control, if that player lost less than 8 life this turn, they lose life equal to the difference.", i = "c34001fd-0e9b-445b-9c0b-381721dfebc2" },
  { n = "Look at Us, We're R&D", t = "Card", c = "", o = "3+ players | 1 pack | 10 min | Pen & Paper\nOBJECTIVE:\nMagic _Magic_ takes a team!! Work together to design and illustrate a unique _Magic_ card.\nGET READY:\nOpen a booster, remove all non-_Magic_ cards and shuffle the rest. Have one player be an artist and another be a writer, then the remaining players will be designers.\nLET'S PLAY:\nThe designers take turns filling out the different parts of a card with pen and paper. To determine these, they draw a random card from the pack, pick one of the categories, and copy it from the card (if it's missing the category you want, draw another). The designers continue until these are all filled in:", i = "80755ccc-6725-4d31-b6f6-e5eb7210669d" },
  { n = "Lotus", t = "Token Artifact", c = "", o = "{T}, Sacrifice this token: Add three mana of any one color.", i = "c59b7223-00a9-4c0d-896d-1cd463860c40" },
  { n = "Lukka, Wayward Bonder Emblem", t = "Emblem", c = "", o = "Whenever a creature enters the battlefield under your control, it deals damage equal to its power to any target.", i = "1e090a47-3187-44f2-9dea-c2bc1407b053" },
  { n = "Maddened Oread", t = "Enchantment Creature — Nymph Reveler", p = "4", u = "2", c = "", o = "As long as five or more Revelers are on the battlefield, Maddened Oread attacks each turn if able.\nHero's Reward — When Maddened Oread leaves the battlefield, each player gains 3 life.", i = "076ad38c-30ec-41a4-be18-c287f65d1d86" },
  { n = "Magic and Minions", t = "Card", c = "", o = "4 players | 2 packs | 45 minutes | d6\nOBJECTIVE:\nUse the cards in a booster to inspire your own one-shot adventure!\nGET READY:\nPick one player to be the *Dungeon Master* (DM). The DM opens a booster and selects a hand of 6 non-land _Magic_ cards to inspire the adventure. They then open a second booster and deal 4 non-land _Magic_ cards to each of the three other players. These cards represent *actions*. Discard all remaining cards.\n*Actions:* Card color represents the *type* of action, and mana value represents its *power*.\n• White = Charisma (coercion, leadership, etc.)\n• Blue = Intelligence (investigation, knowledge, arcane lore, etc.)\n• Black = Strength (melee attacks, climbing, moving large objects, etc.)\n• Red = Dexterity (ranged attacks, dodging, sleight of hand, etc.)\n• Green = Wisdom (common sense, intuition, empathy, etc.)\n• Colorless = Constitution (running, swimming, resisting disease, etc.)", i = "3babdb30-3be2-4a8c-a2a8-95947e40cf64" },
  { n = "Magic Origins Checklist", t = "Card", c = "", o = "(You can mark this card to represent a double-faced Planeswalker card in your library or hand.)\n☐ Kytheon, Hero of Akros {W}\n☐ Jace, Vryn's Prodigy {1}{U}\n☐ Liliana, Heretical Healer {1}{B}{B}\n☐ Chandra, Fire of Kaladesh {1}{R}{R}\n☐ Nissa, Vastwood Seer {2}{G}", i = "f3dcc7b5-c911-44c9-be5a-087298ddb492" },
  { n = "Manifest", t = "Creature", p = "2", u = "2", c = "", o = "(You can cover a face-down manifested creature with this reminder card.\nA manifested creature card can be turned face up any time for its mana cost. A face-down card can also be turned face up for its morph cost.)", i = "0eb1e449-d7ce-4d87-a589-7ae5e3f0951d" },
  { n = "Manifold Mouse", t = "Token Creature — Mouse Soldier", p = "1", u = "1", c = "R", o = "At the beginning of combat on your turn, target Mouse you control gains your choice of double strike or trample until end of turn.\n(This token's mana cost is {1}{R}.)", i = "f5067c54-0f31-40e6-9ead-5d0183c9f00a" },
  { n = "Manuel Bevand Bio", t = "Card", c = "", o = "Pro Tour™ veteran Manuel Bevand played an artifact-based combo deck to a perfect 6-0 record on the Standard day at Worlds. His deck uses Krark-Clan Ironworks to quickly get a Myr Incubator into play, which then creates thirty or more 1/1 Myr creatures—sometimes as early as the third turn! A twenty-seven-year-old freelance game designer from Paris, France, Bevand has been a Magic® regular since 1994, playing in over a dozen Pro Tour events. He credits Magic Online for getting him back into championship form.", i = "f127bd8b-64fd-4fde-b520-345ed27a8585" },
  { n = "Manuel Bevand Decklist", t = "Card", c = "", o = "", i = "836c1c87-7542-45e5-9bdc-73b9c6df1c0f" },
  { n = "Map", t = "Token Artifact — Map", c = "", o = "{1}, {T}, Sacrifice this artifact: Target creature you control explores. Activate only as a sorcery. (Reveal the top card of your library. Put that card into your hand if it's a land. Otherwise, put a +1/+1 counter on that creature, then put the card back or put it into your graveyard.)", i = "91613970-c25c-4959-b5b0-b6e2a7657634" },
  { n = "Marit Lage", t = "Token Legendary Creature — Avatar", p = "20", u = "20", c = "B", o = "Flying, indestructible", i = "25fca5a7-3b61-4e1e-83a3-a312c06fd922" },
  { n = "Mark Le Pine Bio", t = "Card", c = "", o = "Though only 17 years old, New Hampshire—native Mark Le Pine is a Pro Tour veteran. He has been with the Pro Tour since Atlanta '96 and has made the Top 8 three times (Mainz '97, Rome '98, and Worlds '99). Le Pine played an aggressive red deck called \"Sped Red.\" With his deck he applied pressure early with 11 fast creatures, then he'd shift into land-destruction mode with Wasteland, Stone Rain, Pillage, and Avalanche Riders. For the late game Le Pine used Cursed Scroll and Hammer of Bogardan to finish off his mana-crippled opponent.", i = "3a959416-27be-4c92-ac4b-0404529ca978" },
  { n = "Mark Le Pine Decklist", t = "Card", c = "", o = "", i = "3ed7790c-72db-490d-a427-f3202d730aab" },
  { n = "Mark of the Rani", t = "Token Enchantment — Aura", c = "R", o = "Enchant creature\nEnchanted creature gets +2/+2 and is goaded.", i = "7a4c1206-c36f-4fb4-9014-e8a822c97085" },
  { n = "Mask", t = "Token Enchantment — Aura", c = "W", o = "Enchant permanent\nTotem armor (If enchanted permanent would be destroyed, instead remove all damage from it and destroy this Aura.)", i = "b21b5504-c5ef-4dfc-8219-8db90aca7694" },
  { n = "Matt Linde Bio", t = "Card", c = "", o = "Semifinalist Matt Linde is no stranger to high-level Magic® competition. The 18-year-old Maryland native was the 1998 U.S. National Champion. Linde played a very fast mono-green \"Stompy\" deck with 26 creatures—24 of which cost two mana or less to play. Supplementing this furious creature assault were four Rancors and four Giant Growths. Though the deck was designed to win by turn five, it did feature four Cursed Scrolls in case the game dragged on.", i = "24af7223-40ba-4bc3-93f7-12cafa8090b2" },
  { n = "Matt Linde Decklist", t = "Card", c = "", o = "", i = "72dd6b5f-f95b-48f8-a126-0ade77f0f638" },
  { n = "Mechtitan", t = "Token Legendary Artifact Creature — Construct", p = "10", u = "10", c = "BGRUW", o = "Mechtitan is all colors.\nFlying, vigilance, trample, lifelink, haste", i = "0281825d-9d38-4b56-b522-a8d3cf8c77c9" },
