  { n = "Merfolk", t = "Token Creature — Merfolk", p = "1", u = "1", c = "U", o = "Hexproof (This creature can't be the target of spells or abilities your opponents control.)", i = "90317f5e-d121-4c00-86cc-5bbee953f600" },
