  { n = "Meteorite", t = "Token Artifact", c = "", o = "When Meteorite enters the battlefield, it deals 2 damage to any target.\n{T}: Add one mana of any color.", i = "00b41ca9-0bf0-41fc-af65-854e602ee007" },
  { n = "Mimic Match", t = "Card", c = "", o = "2-4 players | 2+ packs | 10 minutes\nOBJECTIVE: Match and collect the most treasure chests before someone uncovers the mimics hiding amongst the loot!\nGET READY: Open one booster per player and remove any lands and cards without _Magic_ card backs, and then shuffle them together. Then put *two lands* back into the deck (to represent the mimics) and shuffle. Deal 16 cards face down in a *4x4 grid*. Randomly determine who goes first.\nLET'S PLAY:\nOn your turn, secretly look at *two cards* from the grid. If they share a *color* or *mana value*, you may reveal them, announce what matches and take those cards, then take another turn.", i = "9de46c01-f2d9-44d4-af72-242b6283ec30" },
  { n = "Mini-Master", t = "Card", c = "", o = "2 players | 2 packs. 10 minutes | Basic Lands\nOBJECTIVE:\nPlay a quick game of Magic using only the cards in a single pack. You may also know this game as Pack Wars!\nGET READY:\nEach player opens a pack and sets aside any cards without Magic card backs, trying not to look at the rest of the cards. Then they add three of each basic land (Plains, Island, Swamp, Mountain, and Forest) to their pack and shuffle. This becomes the player's deck.\nLET'S PLAY:\nRandomly determine who goes first, then play a game of Magic! There are many variants of Mini-Master. The following are modified rules you can add to your game:", i = "279ee746-26b8-4a97-90da-8e5dbb5ccc22" },
  { n = "Minion", t = "Token Creature — Minion", p = "*", u = "*", c = "B", o = "", i = "a9930d11-4772-4fc2-abbd-9af0a9b23a3e" },
  { n = "Minotaur", t = "Token Creature — Minotaur", p = "2", u = "3", c = "R", o = "", i = "5d2a3833-ab5b-4f84-b39c-d0eeb7b474d3" },
  { n = "Minotaur Goreseeker", t = "Creature — Minotaur", p = "3", u = "2", c = "", o = "Haste\nMinotaur Goreseeker attacks each turn if able.", i = "3d2f2bcc-0db9-4aa1-b63d-587c62468015" },
  { n = "Minotaur Younghorn", t = "Creature — Minotaur", p = "2", u = "2", c = "", o = "Haste\nMinotaur Younghorn attacks each turn if able.", i = "2c8e22f9-6b70-425c-a0a8-09b6101a286e" },
  { n = "Mishra's Manufactory", t = "Card", c = "", o = "2-4 players | 2-4 packs | 10 min\nOBJECTIVE:\nTake on the role of one of Mishra's assembly workers and assemble the best invention from the mishmash of parts streaming down the conveyor belt. Strategically collect cards based on their color to win.\nGET READY:\nOpen one booster for each player, remove all cards without _Magic_ card backs, and shuffle the rest together. Reveal four cards in a row stretching from the deck. These form the *conveyor belt*. The two cards closest to the deck are at the *back of the line* and the other two cards are at the *front*. Randomly determine who goes first.\nLET'S PLAY:\nOn their turn, each player drafts one card from the conveyor belt. The two cards at the front of the line are free, but a player must discard a card they've already collected to draft a card from the back of the", i = "52cabb9a-b6b1-4770-b90c-b6484d818a4d" },
  { n = "Mishra's Warform", t = "Token Artifact Creature — Construct", p = "4", u = "4", c = "", o = "(This token has the abilities and other types of the copied artifact.)", i = "287ccbc9-2ffa-4fb3-97d8-2bd469c9411a" },
  { n = "Mogis's Chosen", t = "Creature — Minotaur", p = "5", u = "4", c = "", o = "Mogis's Chosen enters the battlefield tapped.\nMogis's Chosen attacks each turn if able.", i = "553ae9d2-3807-4ca8-a575-7fa6667ee212" },
