  { n = "Monk", t = "Token Creature — Monk", p = "1", u = "1", c = "R", o = "Prowess (Whenever you cast a noncreature spell, this creature gets +1/+1 until end of turn.)", i = "e49c80ac-5c90-4fd2-ad40-cc77af160f64" },
