  { n = "Necron Warrior", t = "Token Artifact Creature — Necron Warrior", p = "2", u = "2", c = "B", o = "", i = "542b3490-1247-4f47-98b6-c67cabae53cb" },
  { n = "Nicolas Labarre Bio", t = "Card", c = "", o = "The 2000 World Championships was Nicolas Labarre's third Top 8 finish at a Pro Tour™ event (Rome '98, New York '99, Worlds '00). This Rennes, France native played a combo deck that he called \"Chimera.\" This deck used searching cards like Academy Rector and Enlightened Tutor to fetch Fecundity, Saproling Cluster, and Ashnod's Altar. Once those three cards were in play, Labarre could generate as much mana as he wanted. With unlimited mana, he could play a very big Blaze or use Whetstone to immediately deck his opponent.", i = "260e570f-e86f-4c7f-ae69-c601de1405d8" },
