  { n = "Paul McCabe Bio", t = "Card", c = "", o = "McCabe, a nineteen-year-old college student from Toronto, Canada, played a fast red-blue attacking deck. The deck's main strategy is to put the opponent on the defensive, using a large number of inexpensive, efficient creatures such as Suq'Ata Lancer, Cloud Elemental, Ophidian, and Man-o'-War. It also makes good use of several \"pitch\" spells like Force of Will and Pyrokinesis.", i = "09901fef-3daf-4890-9d8f-466881326cbd" },
  { n = "Paul McCabe Decklist", t = "Card", c = "", o = "", i = "c2c46b99-4056-428a-ae35-8ba018bb034f" },
  { n = "Pawpatch Recruit", t = "Token Creature — Rabbit Warrior", p = "1", u = "1", c = "G", o = "Trample\nWhenever a creature you control becomes the target of a spell or ability an opponent controls, put a +1/+1 counter on target creature you control other than that creature.\n(This token's mana cost is {G}.)", i = "7cdd8679-93a7-4e58-a6f3-b48897697e89" },
  { n = "Peer Kröger Bio", t = "Card", c = "", o = "Hometown hero Peer Kröger played his own version of the classic \"Reanimator\" deck to an impressive record during this year's World Championships. The twenty-eight-year-old communications and computer science student nicknamed his deck \"Herbert Wise\" after the famous H. P. Lovecraft work \"Herbert Wise—Reanimator.\" Winning with this deck is a two-step process: Step 1. Use Entomb or Buried Alive to quickly get daunting creatures into the graveyard. Step 2. Bring the creature back to life with Zombify or Doomed Necromancer. The mostly black deck also uses Burning Wish to find just the right answers to deal with opponents' plans.", i = "6a45947b-7832-4a0b-836b-63693bf550f8" },
