  { n = "Randy Buehler Bio", t = "Card", c = "", o = "Although twenty-six-year-old professional Magic® player Randy Buehler of Pittsburgh, Pennsylvania, didn't make the Top 8, he did finish with an impressive 6—1 record during the Standard portion of the World Championships. Buehler's Draw, Go deck is built for pure control with over twenty counters. He uses eight card-drawing spells to get to his counters more quickly and only four Stalking Stones and one Rainbow Efreet for offensive power. Buehler said he won some games without ever having to tap a land for mana on his own turn.", i = "23239786-8ac6-460c-9c19-c439b8fa9734" },
  { n = "Randy Buehler Decklist", t = "Card", c = "", o = "", i = "7db7d019-aabb-4436-a570-e2280dc2d368" },
  { n = "Raphael Levy Bio", t = "Card", c = "", o = "A native of Toulouse, France, Raphael Levy posted an impressive 5-1 record during the Standard portion of this year's Worlds playing a blue-green deck he named \"Le Wonder Goose.\" This deck used lots of small creatures—like Numble Mongoose and Werebear—that get bigger at threshold. The deck used blue not for countermagic, but for cards like Careful Study and Mental Note, which help the deck reach threshold more quickly, and for Wonder in the graveyard, which allows the deck's pumped-up threshold creatures to fly.", i = "9464681a-9478-4f87-b22d-c32b9cbb0832" },
  { n = "Raphael Levy Decklist", t = "Card", c = "", o = "", i = "9b787cb5-4c62-4dc4-baf8-fe7a2c87e4b8" },
