  { n = "Sim Han How Bio", t = "Card", c = "", o = "Malaysian National Champion Sim Han How raised some eyebrows by posting a 6-0 record with his blue-green-red \"Squirrel Opposition\" deck. This deck tried to get out lots of Squirrel tokens with Squirrel Nest before using Opposition to tie up the opponent's creatures and mana. Han How won quite a few games using some tricky sideboarding, such as pulling out his enchantments and bringing in more beatdown cards like Flametongue Kavu and Roar of the Wurm. Besides being a top Magic® player, Han How is also a student at Bandar Utama College in Kuala Lumpur, Malaysia.", i = "73bb5b31-d562-4c2f-af92-b995abb8d6eb" },
