  { n = "Tom van de Logt Bio (2000)", t = "Card", c = "", o = "Quarterfinalist Tom van de Logt posted a perfect 6—0 record during the Standard portion of this year's World Championships. The 19-year-old Groesbeek, Holland native was playing a deck that had a big impact on the metagame this year, \"Replenish.\" This deck used cards like Attunement and Frantic Search to put powerful enchantments, such as Parallax Wave and Opalescence, into the graveyard and then used Replenish to put them all back into play at once.", i = "4330efa7-a11b-4776-9fb0-1cae8aed67b1" },
  { n = "Tom van de Logt Bio (2001)", t = "Card", c = "", o = "Tom van de Logt is the 2001 Netherlands National Champion as well as one of an elite group of players who have posted back-to-back World Championship Top 8 performances. Currently a student in Groesbeek, van de Logt posted an impressive 5—1 record in the Standard portion of this year's Worlds. He described his aggressive black-red \"Machine Head\" deck as \"the deck that beats the deck that beats 'Fires.'\" He liked the explosive \"I win\" draws that his deck provided, and he especially liked the way it performed against blue decks.", i = "67f1746f-4f15-48da-9de7-3dd62811afdb" },
