  { n = "Undercity", t = "Dungeon — Undercity", c = "", o = "You can't enter this dungeon unless you \"venture into Undercity.\"\nSecret Entrance — Search your library for a basic land card, reveal it, put it into your hand, then shuffle. (Leads to: Forge, Lost Well)\nForge — Put two +1/+1 counters on target creature. (Leads to: Trap!, Arena)\nLost Well — Scry 2. (Leads to: Arena, Stash)\nTrap! — Target player loses 5 life. (Leads to: Archives)\nArena — Goad target creature. (Leads to: Archives, Catacombs)\nStash — Create a Treasure token. (Leads to: Catacombs)\nArchives — Draw a card. (Leads to: Throne of the Dead Three)\nCatacombs — Create a 4/1 black Skeleton creature token with menace. (Leads to: Throne of the Dead Three)\nThrone of the Dead Three — Reveal the top ten cards of your library. Put a creature card from among them onto the battlefield with three +1/+1 counters on it. It gains hexproof until your next turn. Then shuffle.", i = "2c65185b-6cf0-451d-985e-56aa45d9a57d" },
  { n = "Unwavering Initiate", t = "Token Creature — Zombie Human Warrior", p = "3", u = "2", c = "W", o = "Vigilance", i = "07ab720d-40fc-4315-bc8d-c7073cea588b" },
  { n = "Urza's Blueprints (minigame)", t = "Card", c = "", o = "2+ players | 2+ packs | 10 min\nOBJECTIVE:\nYou've unearthed Urza's ancient blueprints for his Power Plant, Tower, and Mine! Race your fellow artificers to assemble all three iconic locations.\nGET READY:\nOpen a booster for each player and remove any cards without _Magic_ card backs. Shuffle the remaining cards into a deck and deal five cards to each player. Randomly determine who goes first.\nLET'S PLAY:\nOn each player's turn, they draw a card, then discard a card face up. Players may draw either the top card of the deck or the top card of the discard pile. If there are no cards left in the deck when a player tries to draw, shuffle the discard pile to form a new deck.", i = "b3ccdedf-06b9-414e-9abe-643f86dab1eb" },
