  { n = "Wolfgang Eder Bio", t = "Card", c = "", o = "Wolfgang Eder introduced this black-red \"Goblin Bidding\" deck to the world at this year's European Championships. The twenty-two-year-old student from Weinheim, Germany, says the inspiration for the deck came from trying to give the typical Goblin tribe something to do in the midgame. He achieved this by adding black to the deck for Patriarch's Bidding, which brings every Goblin in the graveyard back to play. And with cards like Goblin Warchief and Siege-Gang Commander, those Goblins have haste and bring friends with them! A resolved Patriarch's Bidding is usually game over.", i = "53b08fa1-f76a-407a-ba07-43cadc13453c" },
